/**
 * Penny-vs-PocketSmith balance reconciliation (the product review's P0 trust
 * surface). Pure functions over already-fetched data so the maths is unit-tested
 * without a live network or bun:sqlite.
 *
 * For every account of interest this compares:
 *   - PocketSmith's live reported current_balance, and
 *   - Penny's computed figure: the net of the posted transactions Penny holds for
 *     that account (signed cents; pending excluded, transfers INCLUDED because the
 *     account balance reflects them too).
 *
 * The flagship line is the Credit Card Holding vs card tripwire (ISC-37, ISC-43):
 * Penny's card-spend net should mirror the card's reported balance. A material
 * drift there is the named euphoric surprise firing for a real reason (missing
 * history, a mishandled card-payment transfer) rather than a benign one. Deposit
 * accounts are reported for coverage/transparency but not graded, because Penny is
 * envelope-first and never carried an account opening balance, so a non-zero drift
 * on a bank account is expected, not a fault.
 *
 * Money is integer cents throughout; the only float boundary is PocketSmith's
 * decimal-dollar current_balance, converted once with rounding.
 */

/** A transaction as the reconciler needs it (a narrowed view of the store Tx). */
export interface ReconcileTxn {
  readonly accountId: string;
  readonly amountCents: number;
  readonly isPending: boolean;
}

/** A PocketSmith transaction account as the reconciler needs it. */
export interface ReconcileAccount {
  readonly id: string;
  readonly title: string;
  /** PocketSmith account type, e.g. "bank", "credits", "cash". */
  readonly type: string;
  /** Decimal-dollar current balance reported by PocketSmith (may be undefined). */
  readonly currentBalance: number | undefined;
}

/** One reconciliation line: Penny's figure vs PocketSmith's, and the drift. */
export interface ReconcileBalanceLine {
  readonly accountId: string;
  readonly label: string;
  /** "card" lines are the graded tripwire; "account" lines are informational. */
  readonly kind: "card" | "account";
  readonly pocketsmithCents: number;
  /** Net of Penny's posted transactions on this account (signed cents). */
  readonly pennyCents: number;
  readonly pennyTxnCount: number;
  /** pennyCents - pocketsmithCents. */
  readonly driftCents: number;
  /** ok = ties within tolerance; amber = card drift beyond tolerance; info = ungraded. */
  readonly state: "ok" | "amber" | "info";
}

/** Within this drift a graded (card) line is considered tied. $1.00. */
export const RECONCILE_TOLERANCE_CENTS = 100;

/** Decimal dollars to integer cents, rounding away float dust (mirrors ingest/map). */
function dollarsToCents(amount: number | undefined): number {
  if (amount === undefined || Number.isNaN(amount)) return 0;
  return Math.round(amount * 100);
}

/**
 * Build the reconciliation lines. `cardAccountIds` forces specific accounts to be
 * graded as the holding/card tripwire; any account PocketSmith types as "credits"
 * is also treated as a card. Only accounts Penny tracks (has transactions for) or
 * that carry a non-zero reported balance are included, so dormant zero-balance
 * feeds do not clutter the surface.
 */
export function buildBalanceLines(
  accounts: readonly ReconcileAccount[],
  txns: readonly ReconcileTxn[],
  cardAccountIds: readonly string[] = [],
): ReconcileBalanceLine[] {
  const cardSet = new Set(cardAccountIds);

  // Penny's net + count per account, posted only (pending excluded), transfers
