  // Penny's net + count per account, posted only (pending excluded), transfers
  // included so the figure is comparable to a reported account balance.
  const netByAccount = new Map<string, number>();
  const countByAccount = new Map<string, number>();
  for (const t of txns) {
    if (t.isPending) continue;
    netByAccount.set(t.accountId, (netByAccount.get(t.accountId) ?? 0) + t.amountCents);
    countByAccount.set(t.accountId, (countByAccount.get(t.accountId) ?? 0) + 1);
  }

  const lines: ReconcileBalanceLine[] = [];
  for (const acc of accounts) {
    const pennyCents = netByAccount.get(acc.id) ?? 0;
    const pennyTxnCount = countByAccount.get(acc.id) ?? 0;
    const pocketsmithCents = dollarsToCents(acc.currentBalance);
    const tracked = pennyTxnCount > 0;
    // Skip dormant accounts: no Penny activity and nothing reported.
    if (!tracked && pocketsmithCents === 0) continue;

    // Grade a line as the holding/card tripwire only when it is the active card:
    // either explicitly configured (nabCardAccountIds) or a credit account that
    // still carries a live reported balance. A dormant/closed credit feed (zero
    // reported balance, only historical Penny rows) is shown for coverage, not
    // graded, so it never cries wolf alongside the real card.
    const isCard = cardSet.has(acc.id) || (acc.type === "credits" && pocketsmithCents !== 0);
    const driftCents = pennyCents - pocketsmithCents;
    const state: ReconcileBalanceLine["state"] = isCard
      ? Math.abs(driftCents) <= RECONCILE_TOLERANCE_CENTS
        ? "ok"
        : "amber"
      : "info";
    lines.push({
      accountId: acc.id,
      label: acc.title,
      kind: isCard ? "card" : "account",
      pocketsmithCents,
      pennyCents,
      pennyTxnCount,
      driftCents,
      state,
    });
  }

  // Cards first (the graded tripwire), then accounts by descending |balance|.
  lines.sort((a, b) => {
    if (a.kind !== b.kind) return a.kind === "card" ? -1 : 1;
    return Math.abs(b.pocketsmithCents) - Math.abs(a.pocketsmithCents);
  });
  return lines;
}
