private async buildGrid(
  userId: UserId,
  range: MonthRange,
  asOf?: string,
  includeArchived = false,
): Promise<GridResponse> {
  const target = range.to;
  const [allEnvelopes, txs, mappings, envelopeCarryover, template, movements] = await Promise.all([
    this.store.listEnvelopes(userId),
    this.store.listTransactions(userId),
    this.store.listMappings(userId),
    this.store.listEnvelopeCarryover(userId),
    this.store.listTemplate(userId),
    this.store.listMovements(userId),
  ]);
  // Archived envelopes are excluded ENTIRELY from the grid: not shown, not in any
  // total, not in the zero-base (their transactions still resolve via the surviving
  // mappings, the envelope is simply hidden). getDetail opts back in so the detail
  // page can still load an archived envelope to unarchive it.
  const envelopes = includeArchived
    ? allEnvelopes
    : allEnvelopes.filter((e) => e.archived !== true);
  // Working envelopes are tracked (they keep their rows and actuals) but sit OUTSIDE
  // the zero-based budget: their allocations are excluded from budgetedOut so the
  // residual is unchanged by them.
  const workingIds = new Set(
    envelopes.filter((e) => (e.type ?? "expense") === "working").map((e) => e.id),
  );
  // Per-row budget period label: the CURRENT version's cadence (the line
  // contributing to the target month with the latest effectiveFrom).
  const templatePeriods = new Map<string, BudgetPeriod>();
  for (const e of envelopes) {
    const line = currentLineFor(template, e.id, target);
    if (line !== null) templatePeriods.set(e.id, line.period ?? "monthly");
  }

  // Bucket-to-bucket transfers (owner directive 2026-08-12): each movement is
  // signed activity on BOTH envelopes — a line item, never a budget edit. Net
  // per envelope per calendar month (in the budget timezone).
  const movementByMonth = new Map<string, Map<string, number>>();
  for (const m of movements) {
    const key = todayISO(this.tz, new Date(m.ts)).slice(0, 7);
    let bucket = movementByMonth.get(key);
    if (bucket === undefined) {
      bucket = new Map<string, number>();
      movementByMonth.set(key, bucket);
    }
    bucket.set(m.fromEnvelopeId, (bucket.get(m.fromEnvelopeId) ?? 0) - m.amountCents);
    bucket.set(m.toEnvelopeId, (bucket.get(m.toEnvelopeId) ?? 0) + m.amountCents);
  }
  const movementFor = (p: Period, envelopeId: string): number =>
    movementByMonth.get(periodKey(p))?.get(envelopeId) ?? 0;

  // Roll-forward carryover (owner directive 2026-08-12: "the left value should
  // always be how much is left in the envelope — it should roll over"). Each
  // stored baseline is the OPENING carryover of its capture month
  // (carryoverAnchor: the last manual reset, or the initial import; falls back
  // to rolloverStart for baselines never explicitly captured). The fold
  // advances it to range.from applying (budget + activity + movements) per
  // intervening month under the envelope's rollover rule — so a July charge
  // draws an August carryover down, and unspent budget rolls forward.
  // Allocation for an intervening month comes from its materialised rows when
  // the month exists (they carry this-month overrides and prorations), else
  // from template resolution.
  const ruleByEnv = new Map(envelopes.map((e) => [e.id, normaliseRolloverRule(e.rolloverRule)]));
  const preFoldEnvs = envelopeCarryover.filter((c) => {
    const anchor = c.carryoverAnchor ?? c.rolloverStart;
    return anchor !== null && comparePeriods(periodOfDate(anchor), range.from) < 0;
  });
  let preFoldStart = range.from;
  for (const c of preFoldEnvs) {
    const p = periodOfDate((c.carryoverAnchor ?? c.rolloverStart)!);
    if (comparePeriods(p, preFoldStart) < 0) preFoldStart = p;
  }
  const preAllocByMonth = new Map<string, ReadonlyMap<string, number>>();
  const preActivityByMonth = new Map<string, ReadonlyMap<string, number>>();
  for (const p of periodRange(preFoldStart, range.from)) {
    if (comparePeriods(p, range.from) >= 0) break; // months strictly before range.from
    const rows = await this.store.listAllocations(userId, periodKey(p));
    if (rows.length > 0) {
      const byEnv = new Map<string, number>();
      for (const a of rows) byEnv.set(a.envelopeId, (byEnv.get(a.envelopeId) ?? 0) + a.amountCents);
      preAllocByMonth.set(periodKey(p), byEnv);
    } else {
      preAllocByMonth.set(periodKey(p), resolveTemplateForMonth(template, p));
    }
    preActivityByMonth.set(periodKey(p), computeActivity(txs, mappings, this.config, { period: p }).byEnvelope);
  }
  const openingCarryover = new Map<string, number>();
  // Each envelope's OWN folded opening at range.from — the figure the grid
  // displays and the carryover popover must adjust FROM (the raw stored
  // baseline is anchored at capture and diverges once months fold in).
  const ownOpening = new Map<string, number>();
