/**
 * Calendar-month period helpers. The period is Penny's unit of budgeting
 * (ISA LOAD-1). A period key is the ISO YYYY-MM string the contract renders.
 *
 * Everything here is pure and total: no I/O, no clock reads. Callers pass the
 * period explicitly so the engine stays deterministic and testable.
 */

import type { Period } from "../domain/types.ts";

/** Format a period as its canonical YYYY-MM key. */
export function periodKey(p: Period): string {
  return `${p.year}-${String(p.month).padStart(2, "0")}`;
}

/** Parse a YYYY-MM key back into a Period. Throws on malformed input. */
export function parsePeriod(key: string): Period {
  const m = /^(\d{4})-(\d{2})$/.exec(key);
  if (!m) throw new Error(`invalid period key: ${key}`);
  const year = Number(m[1]);
  const month = Number(m[2]);
  if (month < 1 || month > 12) throw new Error(`invalid month in period: ${key}`);
  return { year, month };
}

/** The period a transaction date (YYYY-MM-DD) falls in. */
export function periodOfDate(isoDate: string): Period {
  const year = Number(isoDate.slice(0, 4));
  const month = Number(isoDate.slice(5, 7));
  return { year, month };
