const db=new Database(process.env.HOME+"/.penny/penny.db",{readonly:true});
console.log("sync_state:",JSON.stringify(db.query("SELECT * FROM sync_state").all()));
console.log("max txn date:",JSON.stringify(db.query("SELECT MAX(txn_date) d, COUNT(*) n FROM transactions").get()));
console.log("card rows:",JSON.stringify(db.query(`SELECT COUNT(*) n, SUM(CASE WHEN is_pending=0 THEN amount_cents ELSE 0 END) posted, SUM(CASE WHEN is_pending=1 THEN amount_cents ELSE 0 END) pending FROM transactions WHERE account_id=\"4771153\"`).get()));
console.log("recent events:",JSON.stringify(db.query("SELECT * FROM events ORDER BY rowid DESC LIMIT 5").all()).slice(0,800));
'

